        FlowLayoutPanel ScrollPage() {var p=Flow(true);p.AutoSize=false;p.Dock=DockStyle.Fill;p.AutoScroll=true;p.Padding=new Padding(0,4,16,16);content.Controls.Add(p);p.BringToFront();return p;}
        FlowLayoutPanel Card(string title,int width=760) {var card=new SurfaceFlow{AutoSize=true,FlowDirection=FlowDirection.TopDown,WrapContents=false};card.Padding=new Padding(22);card.Margin=new Padding(0,0,0,14);card.Width=width;card.MinimumSize=new Size(width,0);card.MaximumSize=new Size(width,0);if(title.Length>0)card.Controls.Add(L(title,12,true));
            Action fit=()=>{if(card.Parent==null||card.IsDisposed)return;int available=Math.Max(320,card.Parent.ClientSize.Width-card.Parent.Padding.Horizontal-SystemInformation.VerticalScrollBarWidth-8);card.MaximumSize=new Size(Math.Min(width,available),0);card.MinimumSize=new Size(Math.Min(width,available),0);card.Width=Math.Min(width,available);FitCardChildren(card,card.Width-card.Padding.Horizontal);};
            card.ParentChanged+=(s,e)=>{if(card.Parent==null)return;var parent=card.Parent;EventHandler changed=(a,b)=>fit();parent.SizeChanged+=changed;card.Disposed+=(a,b)=>parent.SizeChanged-=changed;fit();};card.ControlAdded+=(s,e)=>{WatchCardChild(e.Control,fit);fit();};return card;}
        void WatchCardChild(Control control,Action fit) {control.ControlAdded+=(s,e)=>{WatchCardChild(e.Control,fit);fit();};foreach(Control child in control.Controls)WatchCardChild(child,fit);}
        void FitCardChildren(Control parent,int width) {foreach(Control child in parent.Controls){int maximum=Math.Max(120,width-child.Margin.Horizontal);if(child is FlowLayoutPanel){child.MaximumSize=new Size(maximum,0);FitCardChildren(child,maximum-child.Padding.Horizontal);}else {if(child.Width>maximum)child.Width=maximum;if(child is Label)child.MaximumSize=new Size(maximum,0);}}}
        void ShowDevices() {Title("连接设备","与手机端使用相同的加密配对和连接权限");var scroll=ScrollPage();var local=Card("本机");var identity=hub.Identity();local.Controls.Add(L(J.Str(vault.State,"name")+"  ·  "+string.Join(" / ",hub.Addresses),10,true));local.Controls.Add(L(T("配对码")+"  "+J.Str(identity,"pair_code"),18,true));local.Controls.Add(L(T("设备标识")+"  "+J.Str(identity,"device_id").Substring(0,16)+"…",9));if(hub.Error.Length>0)local.Controls.Add(L(hub.Error,10));scroll.Controls.Add(local);
            var connect=Card("添加设备");var row=Flow();row.Controls.Add(B("局域网搜索",()=>Async(SearchDevices),true,130));var codeField=Field("");codeField.Width=130;codeField.MaxLength=6;codeField.AccessibleName=T("配对码");row.Controls.Add(codeField);row.Controls.Add(B("配对码连接",()=>Async(async()=>{if(codeField.Text.Length!=6||!codeField.Text.All(char.IsDigit))throw new Exception("请输入 6 位配对码");if(discovery!=null)discovery.Cancel();discovery=new CancellationTokenSource();var found=await hub.Discover(discovery.Token);var matches=found.Where(x=>J.Str(x,"pair_code")==codeField.Text).ToArray();if(matches.Length!=1)throw new Exception(matches.Length==0?"未找到设备，请使用 IP 连接":"配对码重复，请使用 IP 连接");await PairDevice(matches[0]);}),false,120));connect.Controls.Add(row);var iprow=Flow();var host=Field("");host.Width=240;host.AccessibleName=T("设备 IP");var port=Field("18769");port.Width=80;port.AccessibleName=T("控制端口");iprow.Controls.Add(L("IP",10));iprow.Controls.Add(host);iprow.Controls.Add(port);iprow.Controls.Add(B("申请连接",()=>Async(async()=>{int n;if(!int.TryParse(port.Text,out n))throw new Exception("端口无效");await PairDevice(await hub.DeviceAt(host.Text.Trim(),n,CancellationToken.None));}),false,110));connect.Controls.Add(iprow);connectionState=L("对方允许后连接。配对码用于查找设备，设备身份由密钥标识识别。",9);connect.Controls.Add(connectionState);foundPanel=Flow(true);connect.Controls.Add(foundPanel);scroll.Controls.Add(connect);pendingPanel=Card("连接申请");scroll.Controls.Add(pendingPanel);peersPanel=Card("已配对设备");scroll.Controls.Add(peersPanel);RefreshDevices();}
        async Task SearchDevices() {if(discovery!=null)discovery.Cancel();discovery=new CancellationTokenSource();var token=discovery.Token;connectionState.Text=T("正在搜索…");var found=await hub.Discover(token);if(page!="devices")return;foundPanel.Controls.Clear();foreach(var info in found){var current=info;var row=Flow();row.Controls.Add(L(J.Str(info,"name")+" · "+J.Str(info,"host"),10));row.Controls.Add(B("申请连接",()=>Async(()=>PairDevice(current)),false,110));foundPanel.Controls.Add(row);}connectionState.Text=found.Count>0?T("请选择设备"):T("未找到设备，请使用 IP 连接");}
        async Task PairDevice(object info) {connectionState.Text=T("正在申请连接…");using(var cancel=new CancellationTokenSource(TimeSpan.FromSeconds(120))){var result=await hub.Begin(info,cancel.Token);while(J.Str(result,"status")=="pending"){if(page=="devices")connectionState.Text=T("等待对方确认")+" · "+T("确认码")+" "+J.Str(result,"code");await Task.Delay(1500,cancel.Token);result=await hub.Poll(J.Str(result,"id"),false,cancel.Token);}if(page=="devices"){connectionState.Text=T(J.Str(result,"status")=="accepted"?"已连接":"对方拒绝了连接");RefreshDevices();}}}
        void RefreshDevices() {if(peersPanel==null||peersPanel.IsDisposed||page!="devices")return;peersPanel.Controls.Clear();peersPanel.Controls.Add(L("已配对设备",12,true));foreach(var p in vault.Peers){var current=p;string id=J.Str(p,"id");var row=Flow();row.Controls.Add(L(J.Str(p,"name")+"  ·  "+J.Str(p,"host")+"  ·  "+T(J.Bool(p,"incoming",true)?"允许控制本机":"可控制对方"),10));if(!J.Bool(p,"incoming",true)){row.Controls.Add(B("设备信息",()=>Async(async()=>{var info=await hub.Request(id,"info",J.Obj(),CancellationToken.None);Prompt("设备信息","设备信息",J.Write(info),true);}),false,94));row.Controls.Add(B("实时屏幕",()=>OpenScreen(current),false,94));row.Controls.Add(B("终端",()=>{terminalTarget=id;Navigate("terminal");},false,70));}row.Controls.Add(B("断开连接",()=>Async(async()=>{if(MessageBox.Show(this,T("确定断开该设备？"),"AsterHand",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;if(!J.Bool(current,"incoming",true))try{await hub.Request(id,"session.close",J.Obj(),CancellationToken.None);}catch{}hub.Revoke(id);RefreshDevices();}),false,94));peersPanel.Controls.Add(row);}if(vault.Peers.Count==0)peersPanel.Controls.Add(L("暂无已配对设备",10));pendingHash="";UpdatePending();}
        void UpdatePending() {if(pendingPanel==null||pendingPanel.IsDisposed)return;var list=hub.Pending();string hash=J.Write(list);if(hash==pendingHash)return;pendingHash=hash;pendingPanel.Controls.Clear();pendingPanel.Controls.Add(L("连接申请",12,true));foreach(var p in list){string id=J.Str(p,"id");pendingPanel.Controls.Add(L(J.Str(p,"name")+" · "+T("确认码")+" "+J.Str(p,"code"),10,true));var row=Flow();row.Controls.Add(B("仅本次允许",()=>hub.Decide(id,"once"),true,130));row.Controls.Add(B("始终允许",()=>hub.Decide(id,"always"),false,110));row.Controls.Add(B("拒绝",()=>hub.Decide(id,"deny"),false,90));pendingPanel.Controls.Add(row);}if(list.Length==0)pendingPanel.Controls.Add(L("暂无连接申请",9));}

        ComboBox TerminalTargets() {var combo=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,FlatStyle=FlatStyle.Flat,Width=240,Margin=new Padding(4,8,8,4)};combo.Items.Add(new Choice("local",T("本机")));foreach(var p in vault.Peers.Where(x=>!J.Bool(x,"incoming",true)))combo.Items.Add(new Choice(J.Str(p,"id"),J.Str(p,"name")));combo.SelectedIndex=0;for(int i=0;i<combo.Items.Count;i++)if(((Choice)combo.Items[i]).Id==terminalTarget)combo.SelectedIndex=i;return combo;}
        async Task<object> TargetCall(string id,string method,object args,CancellationToken ct) {return id=="local"?tools.Terminal(method.Substring(9),args,"ui"):await hub.Request(id,method,args,ct);}
        void ShowTerminal() {if(terminalId.Length>0)terminalOffset=0;Title("终端与文件","持久终端保留目录和变量，文件覆盖前自动备份");var tabs=Design.Tabs();var terminalTab=new TabPage(T("终端")){BackColor=Design.Surface,Padding=new Padding(12)};var filesTab=new TabPage(T("文件")){BackColor=Design.Surface,Padding=new Padding(12)};tabs.TabPages.Add(terminalTab);tabs.TabPages.Add(filesTab);content.Controls.Add(tabs);tabs.BringToFront();var row=Flow();row.Dock=DockStyle.Top;row.Height=48;row.AutoSize=false;var targets=TerminalTargets();row.Controls.Add(targets);row.Controls.Add(B("打开终端",()=>Async(async()=>{if(terminalId.Length>0)await CloseTerminal();terminalTarget=((Choice)targets.SelectedItem).Id;var opened=await TargetCall(terminalTarget,"terminal.open",J.Obj(),CancellationToken.None);terminalId=J.Str(opened,"session");terminalOffset=0;terminalOutput.Clear();if(terminalPoll!=null){terminalPoll.Stop();terminalPoll.Dispose();}terminalPoll=new System.Windows.Forms.Timer{Interval=400};bool reading=false;terminalPoll.Tick+=(s,e)=>{if(reading||terminalId.Length==0||terminalOutput.IsDisposed)return;reading=true;Async(async()=>{try{var output=await TargetCall(terminalTarget,"terminal.read",J.Obj("session",terminalId,"offset",terminalOffset),CancellationToken.None);terminalOffset=(long)J.Num(output,"next_offset",terminalOffset);if(!terminalOutput.IsDisposed){terminalOutput.AppendText(J.Str(output,"output"));if(terminalOutput.TextLength>200000)terminalOutput.Text=terminalOutput.Text.Substring(100000);terminalOutput.SelectionStart=terminalOutput.TextLength;terminalOutput.ScrollToCaret();}if(J.Bool(output,"ended"))terminalPoll.Stop();}finally{reading=false;}});};terminalPoll.Start();}),true,110));row.Controls.Add(B("中断",()=>Async(async()=>{if(terminalId.Length==0)return;await TargetCall(terminalTarget,"terminal.interrupt",J.Obj("session",terminalId),CancellationToken.None);terminalId="";terminalPoll.Stop();}),false,80));row.Controls.Add(B("关闭终端",()=>Async(CloseTerminal),false,100));terminalOutput=new RichTextBox{Dock=DockStyle.Fill,ReadOnly=true,BackColor=Color.FromArgb(24,31,39),ForeColor=Color.FromArgb(218,231,224),Font=new Font("Consolas",10),BorderStyle=BorderStyle.None,DetectUrls=false};var inputRow=new TableLayoutPanel{Dock=DockStyle.Bottom,Height=48,ColumnCount=2};inputRow.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));inputRow.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,100));var input=Field("");input.Dock=DockStyle.Fill;input.AccessibleName=T("终端输入");Action write=()=>Async(async()=>{if(terminalId.Length==0)throw new Exception("请先打开终端");await TargetCall(terminalTarget,"terminal.write",J.Obj("session",terminalId,"text",input.Text+"\n"),CancellationToken.None);input.Clear();});input.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Enter){e.SuppressKeyPress=true;write();}};inputRow.Controls.Add(input,0,0);inputRow.Controls.Add(B("发送",write,true,88),1,0);terminalTab.Controls.Add(terminalOutput);terminalTab.Controls.Add(inputRow);terminalTab.Controls.Add(row);terminalOutput.BringToFront();BuildFiles(filesTab);}
        async Task CloseTerminal() {string id=terminalId;if(id.Length==0)return;terminalId="";if(terminalPoll!=null)terminalPoll.Stop();await TargetCall(terminalTarget,"terminal.close",J.Obj("session",id),CancellationToken.None);}
        internal static string InitialFilePath(string target,string localPath) {return target=="local"?localPath:".";}
        void BuildFiles(TabPage tab) {
            var top=Flow();top.AutoSize=false;top.Dock=DockStyle.Top;top.Height=86;
            var targets=TerminalTargets();targets.AccessibleName=T("执行目标");
            var path=Field(InitialFilePath(((Choice)targets.SelectedItem).Id,tools.Work));path.Width=430;path.AccessibleName=T("文件路径");
            var list=new ListBox{Dock=DockStyle.Left,Width=230,BorderStyle=BorderStyle.FixedSingle,ItemHeight=24};
            var editor=new TextBox{Dock=DockStyle.Fill,Multiline=true,ScrollBars=ScrollBars.Both,WordWrap=false,Font=new Font("Consolas",10),AccessibleName=T("文件内容")};
            int scope=0;
            targets.SelectedIndexChanged+=(s,e)=>{scope++;path.Text=InitialFilePath(((Choice)targets.SelectedItem).Id,tools.Work);list.Items.Clear();editor.Clear();};
            Func<string,object,Task<object>> run=async (name,args)=>{string id=((Choice)targets.SelectedItem).Id;return id=="local"?await tools.Execute(name,args,CancellationToken.None):await hub.Request(id,"execute",J.Obj("tool",name,"arguments",args),CancellationToken.None);};
            Action listing=()=>Async(async()=>{int requestScope=scope;string requested=path.Text;var result=await run("list_directory",J.Obj("path",requested));if(tab.IsDisposed||scope!=requestScope||path.Text!=requested)return;list.Items.Clear();foreach(var item in J.List(J.Get(result,"entries")))list.Items.Add(item is string?(string)item:J.Str(item,"name"));});
            top.Controls.Add(targets);top.Controls.Add(path);top.Controls.Add(B("列出目录",listing,true,100));
            top.Controls.Add(B("读取文件",()=>Async(async()=>{int requestScope=scope;string requested=path.Text;var result=await run("read_file",J.Obj("path",requested,"offset",0));if(!tab.IsDisposed&&scope==requestScope&&path.Text==requested)editor.Text=J.Str(result,"text",J.Str(result,"content"));}),false,100));
            top.Controls.Add(B("保存文件",()=>Async(async()=>{string current=path.Text;if(MessageBox.Show(this,T("保存文件并备份原文件？")+"\n"+current,"AsterHand",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;await run("write_file",J.Obj("path",current,"content",editor.Text));}),false,100));
            list.DoubleClick+=(s,e)=>{if(list.SelectedItem!=null){string separator=((Choice)targets.SelectedItem).Id=="local"?Path.DirectorySeparatorChar.ToString():"/";path.Text=path.Text.TrimEnd('/','\\')+separator+list.SelectedItem;listing();}};
            tab.Controls.Add(editor);tab.Controls.Add(list);tab.Controls.Add(top);editor.BringToFront();
        }

